def test_each_counterparty_matches_its_netting_sets(self):
    result = self.call()
    for cp in result["counterparty_totals"]:
        owned = [
            s for s in result["netting_set_results"]
            if s["counterparty_id"] == cp["id"]
        ]
        for metric in (
            "gross_exposure",
            "net_mtm",
            "potential_future_exposure",
            "exposure_at_default",
            "expected_loss",
        ):
            self.assertTrue(
                math.isclose(
                    cp[metric],
                    sum(s[metric] for s in owned),
                    rel_tol=0.0,
                    abs_tol=1e-9,
                ),
                msg=(cp["id"], metric),
            )

